TITLE = "Nairobi this weekend: 30 October – 1 November"
TAG = "Nairobi This Weekend"
H1 = "Nairobi this weekend: 30 October – 1 November"
DEK = "Halloween lands on a Saturday, the Floodies crown their champions and a classic Kenyan cartoon gets a new book. Here's where to be from Friday to Sunday."
META = "Nairobi This Weekend · 29 Oct 2026 · 4 min read"
LEAD = ("img/nw-skyline.jpg", "Nairobi")

BODY = [
("p", "It's a Halloween weekend, and the city has leaned into it: costume parties for kids and grown-ups, a rock night dressed up for the occasion. But there's plenty for people who'd rather skip the face paint, from a three-day wine fair and a weekend-long comedy at the National Theatre to the biggest night of Kenya's rugby pre-season."),

("h2", "Fri 30 Oct – Sun 1 Nov · Artcaffé, Rhapta Road", "South Africa ", "by the Glass"),
("img", "img/nw2-wine.jpg", "South Africa by the Glass", "Artcaffé Market (poster)"),
("p", "Artcaffé Market and Wines of South Africa are running a three-day wine fair at the Artcaffé on Rhapta Road in Westlands, from Friday 30 October to Sunday 1 November. It's billed simply as “the 3 day wine fair”: a weekend of tastings built around South African wine, with entry at KSh 2,000 per person."),
("p", "Good to know: the price is per person, so budget for the whole group if you're going as a crew."),

("h2", "Fri 30 Oct – Sun 1 Nov · Kenya National Theatre", "Let Me ", "Confess"),
("img", "img/nw2-confess.jpg", "Let Me Confess", "The Crony (poster)"),
("p", "The Crony brings its comedy play <em>Let Me Confess</em> to the Kenya National Theatre for three days, Friday to Sunday. The play is directed by Ndeng'a and produced by Victor Nyaata, and there are two shows each day."),
("p", "The 3pm shows cost KSh 1,500 and the 6:30pm shows cost KSh 2,000, so the matinee is the cheaper way in. Booking details are on Crony Productions' site."),

("h2", "Sat 31 Oct · Impala Club, Ngong Road", "Impala Floodlit ", "Finals"),
("img", "img/nw2-floodlit.jpg", "Impala Floodlit Rugby Tournament", "Supplied"),
("p", "The 43rd Impala Floodlit Tournament, the Floodies, has been played over three Saturdays at Impala Club on Ngong Road, and this is the last of them. Finals day covers every category, including the club, ladies' and university competitions."),
("p", "The headline game is the club final. Ten-time champions KCB Rugby booked their place with a 64–11 thrashing of Mwamba RFC in last week's semi-final, and they'll face Kenya Harlequin for the title."),

("h2", "Sat 31 Oct · Village Market, Gigiri", "Halloween ", "Fright Night"),
("img", "img/nw2-fright.jpg", "Halloween Fright Night", "Village Market (poster)"),
("p", "Village Market's Halloween Fright Night splits the day in two. The Little Monsters kids' party starts at 2pm, and the Villain party takes over from 6pm, with trick-or-treating, music and food on the programme."),
("p", "Tickets are KES 1,500 in advance on Ticketsasa and KES 2,000 at the gate, so it pays to book ahead."),

("h2", "Sat 31 Oct · 3–6pm · KNLS, Upper Hill", "It's a Madd ", "Madd World"),
("img", "img/nw2-madd.jpg", "It's a Madd Madd World! A World Caged! 2012–2016", "Book launch poster"),
("p", "<em>It's a Madd Madd World!</em> is the satirical cartoon page that the cartoonist Maddo, Paul Kelemba, has drawn for The Standard for decades. In 2015 it won him the CNN MultiChoice African Journalist award, and the page has become a weekly record of Kenyan politics and public life told through caricature."),
("p", "A new collection, <em>A World Caged! 2012–2016</em>, launches at the Kenya National Library's Maktaba Kuu building in Upper Hill on Saturday from 3pm to 6pm. Entry is free. It covers years that gave a cartoonist plenty to work with, at home and abroad."),

("h2", "Sat 31 Oct · 7pm · Sarakasi Dome, Ngara", "Rock Riot ", "Halloween"),
("img", "img/nw2-rockriot.jpg", "Rock Riot Halloween Edition", "A-List Events (poster)"),
("p", "Rock Riot, an A-List Events series, puts on a Halloween edition at Sarakasi Dome in Ngara. The lineup is Rash Band, Keni and Nessa Dove, with DJ Orts and DJ Edygrim on the decks."),
("p", "Rash Band are a Swahili rock band from Nairobi. Doors are at 7pm, and tickets are on a-list-events.com. Costumes, given the date, are very much encouraged."),

("h2", "Coming up · from Wed 4 Nov", "Next week: ", "KITFest"),
("p", "Plan ahead for the 11th Kenya International Theatre Festival. It opens on Wednesday 4 November at the Kenya National Theatre and runs to Sunday 15 November, with productions across four stages."),
]

